{
  "title": "Gion and Arashiyama, Close at Hand",
  "summary": "A slower Kyoto day: temples, bamboo and a vegan lunch, all within a short ride.",
  "stops": [
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bamboo first, before the crowds wake up. Shoes off, phone down, eyes up.",
      "poi_id": "p5"
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tenryu-ji sits right by the bamboo, so we keep the temple and skip the long ride.",
      "poi_id": "p6"
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A quiet vegan lunch beside the temple. Kaiseki (multi-course Kyoto meal) for the crew, no compromises.",
      "poi_id": "p16"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "One short ride to Sanjusangen-do. The thousand buddhas are worth it, and the deer will cope without you.",
      "poi_id": "p12"
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "Hanamikoji in the late afternoon: old Kyoto, free, and close to dinner.",
      "poi_id": "p7"
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Kichi Kichi, a short stroll from Hanamikoji. Vegetarian options, and the chef is a show.",
      "poi_id": "p18"
    }
  ]
}
